"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["1594"],{698(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.fato_candidato.ja_ativo","status":422,"titulo":"O fato j\xe1 est\xe1 ativo"},"descricao":{"codigo":"uniplus.configuracao.fato_candidato.ja_ativo","requisitos":["UNI-REQ-0143"],"oQueAconteceu":["O administrador pediu a reativa\xe7\xe3o de um fato do cat\xe1logo (`POST /api/configuracao/admin/fatos-candidato/{id}/ativacao`), mas o fato j\xe1 est\xe1 ativo. Um fato desativado deixa de aceitar v\xednculos novos e preserva os que j\xe1 existem (UNI-REQ-0143), e a reativa\xe7\xe3o o faz voltar a aceit\xe1-los. Repetir o pedido n\xe3o tem efeito, e a API o recusa em vez de aceit\xe1-lo em sil\xeancio.","As confer\xeancias seguem esta ordem: o fato ([fato do candidato n\xe3o encontrado](/erros/uniplus.configuracao.fato_candidato.nao_encontrado)), a recusa de fato de sistema, que n\xe3o \xe9 reativado ([defini\xe7\xe3o do fato de sistema travada](/erros/uniplus.configuracao.fato_candidato.definicao_do_fato_de_sistema_travada)) e, por \xfaltimo, o estado do fato. A resposta n\xe3o traz a lista `errors`. Nada \xe9 gravado."],"comoResolver":["N\xe3o h\xe1 nada a fazer: o fato est\xe1 ativo e aceita v\xednculos novos. Para confirmar o estado, consulte o fato (`GET /api/configuracao/admin/fatos-candidato/{id}`)."],"ondeAparece":["Reativa\xe7\xe3o de um fato do cat\xe1logo"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Fato candidato"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"fd5ea0ff72951399d2b2c1a4f29aeb3ea415db44"}}')}}]);